Certainly! Here’s a minimal **C** example showing a blocking `read()` interrupted by a signal and the proper way to handle `EINTR` (interrupted system call):

**Key Concepts:**
- A blocking `read()` on a file descriptor (like stdin or a pipe).
- A signal handler (e.g., for `SIGALRM`) interrupts the system call.
- `read()` returns `-1` and sets `errno` to `EINTR`.
- Correct code retries the `read()` if `errno == EINTR`.

Here is the example:

```c
#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <stdlib.h>

void sigalrm_handler(int sig) {
    // Just a simple handler to interrupt the read
    printf("Signal handler called with signal %d\n", sig);
}

int main(void) {
    // Set up signal handler for SIGALRM
    struct sigaction sa;
    sa.sa_handler = sigalrm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Set alarm to go off in 3 seconds
    alarm(3);

    char buf[100];
    ssize_t n;

    printf("Please type something (or wait for the alarm):\n");

    // Blocking read, can be interrupted by signal
    while (1) {
        n = read(STDIN_FILENO, buf, sizeof(buf));
        if (n == -1) {
            if (errno == EINTR) {
                printf("read() was interrupted by signal, retrying...\n");
                continue; // Retry the read
            } else {
                perror("read");
                exit(1);
            }
        }
        break; // read succeeded
    }

    printf("Read %zd bytes: %.*s\n", n, (int)n, buf);

    return 0;
}
```

**How to test:**
1. Compile: `gcc -o eintr_demo eintr_demo.c`
2. Run: `./eintr_demo`
3. Either:
   - Wait 3 seconds and observe signal interrupting the `read()`.
   - Or type something before the alarm.

**Expected Output:**
```
Please type something (or wait for the alarm):
# (wait 3 seconds...)
Signal handler called with signal 14
read() was interrupted by signal, retrying...
```
If you now type something, the `read()` will succeed.

---

**Explanation:**  
When `alarm(3)` expires, it sends `SIGALRM`, interrupting the blocking `read()`. The handler prints a message, and `read()` returns `-1` with `errno == EINTR`. The loop detects this and retries the read, as per best practice.

Certainly! Below is a simple C++ program that opens a TCP socket on port `888` and reads incoming network packets. This example is for **Linux/Unix** systems using the BSD sockets API.

It listens for incoming connections, accepts one, and then reads data from the connected client.

---

```cpp
#include <iostream>
#include <cstring>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define PORT 888
#define BUFFER_SIZE 4096

int main() {
    int server_fd, client_fd;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};

    // 1. Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // 2. Forcefully attach socket to the port 888
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY; // Listen on all interfaces
    address.sin_port = htons(PORT);

    // 3. Bind the socket to the network address and port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // 4. Start listening for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    std::cout << "Listening on port " << PORT << "..." << std::endl;

    // 5. Accept an incoming connection
    if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    std::cout << "Connection accepted." << std::endl;

    // 6. Read data from the socket
    ssize_t valread;
    while ((valread = read(client_fd, buffer, BUFFER_SIZE)) > 0) {
        std::cout << "Received " << valread << " bytes: ";
        std::cout.write(buffer, valread);
        std::cout << std::endl;
        memset(buffer, 0, BUFFER_SIZE);
    }

    if (valread < 0) {
        perror("read");
    }

    close(client_fd);
    close(server_fd);

    return 0;
}
```

---

**How to compile:**
```sh
g++ -o tcp_server tcp_server.cpp
```

**How to run:**
```sh
./tcp_server
```

**Test from another terminal:**
```sh
telnet 127.0.0.1 888
# or
nc 127.0.0.1 888
```

---

**Notes:**
- This is a basic example for learning purposes. For production code, add proper error handling, use threads or `select()`/`epoll` for multiple clients, and consider security implications.
- If you want to capture **raw packets** (e.g., at IP layer), you would need raw sockets and usually root privileges. Let me know if you need that!

