let () =
  (* 1. Create OpenGL context using Tsdl *)
  let open Tsdl in
  Sdl.init Sdl.Init.video |> ignore;
  let win =
    Sdl.create_window ~w:100 ~h:100 "Dot Product" Sdl.Window.opengl
    |> Result.get_ok
  in
  ignore (Sdl.gl_create_context win);

  (* 2. Prepare data *)
  let n = 4 in
  let a_data = Array1.of_array float32 c_layout [|1.; 2.; 3.; 4.|] in
  let b_data = Array1.of_array float32 c_layout [|10.; 20.; 30.; 40.|] in
  let result_data = Array1.create float32 c_layout 1 in
  result_data.{0} <- 0.;

  (* 3. Create buffers *)
  let create_ssbo binding ba =
    let buf = Gl.gen_buffer () in
    Gl.bind_buffer Gl.buffer_storage buf;
    let size = Array1.size_in_bytes ba in
    Gl.buffer_data Gl.buffer_storage size (Some (Array1.start ba)) Gl.static_draw;
    Gl.bind_buffer_base Gl.shader_storage_buffer binding buf;
    buf
  in
  let a_buf = create_ssbo 0 a_data in
  let b_buf = create_ssbo 1 b_data in
  let r_buf = create_ssbo 2 result_data in

  (* 4. Compile compute shader *)
  let shader = Gl.create_shader Gl.compute_shader in
  Gl.shader_source shader shader_src;
  Gl.compile_shader shader;
  let compiled = Gl.get_shaderiv shader Gl.compile_status in
  if compiled = 0 then begin
    let log = Gl.get_shader_info_log shader in
    Printf.eprintf "Shader compile error: %s\n%!" log;
    exit 1
  end;
  let prog = Gl.create_program () in
  Gl.attach_shader prog shader;
  Gl.link_program prog;
  let linked = Gl.get_programiv prog Gl.link_status in
  if linked = 0 then begin
    let log = Gl.get_program_info_log prog in
    Printf.eprintf "Program link error: %s\n%!" log;
    exit 1
  end;

  (* 5. Run compute shader *)
  Gl.use_program prog;
  Gl.dispatch_compute n 1 1;
  Gl.memory_barrier Gl.shader_storage_barrier_bit;

  (* 6. Read back result *)
  Gl.bind_buffer Gl.buffer_storage r_buf;
  let ptr = Gl.map_buffer_range Gl.buffer_storage 0 4 Gl.map_read_bit in
  let sum = Ctypes.(coerce (ptr void) (ptr float) ptr) in
  let result = Ctypes.(!@sum) in
  Printf.printf "Dot product = %f\n%!" result;

  (* 7. Cleanup *)
  Gl.unmap_buffer Gl.buffer_storage;
  Gl.delete_program prog;
  Gl.delete_shader shader;
  Gl.delete_buffers [|a_buf; b_buf; r_buf|];
  Sdl.destroy_window win;
  Sdl.quit ();
;;
```

---

### Notes

- This code assumes you have a working OpenGL 4.3+ context, and have installed `lablgl` and `tsdl`.
- The buffer binding and mapping parts might need adaptation depending on your OCaml OpenGL binding (the above is indicative; `LablGL` has a limited buffer API).
- For larger vectors, you’d want to increase `local_size_x` and use workgroup reductions.
- In a real app, always check OpenGL errors and handle resource management more robustly.

