Certainly! Below is a simple example of how you could perform *old-school* raycasting (as in DOOM/Wolfenstein 3D style, not full 3D raytracing) in **GLSL**. In this approach, the vertex shader simply draws a fullscreen quad, and the fragment shader does the raycasting in a 2D grid map to determine wall hits.

Let’s assume you pass a 2D texture as the map (each texel encodes wall/floor), and uniforms for player position/direction.

---

### **Vertex Shader (`raycast.vert`)**

```glsl
#version 330 core

layout(location = 0) in vec2 aPos; // Fullscreen quad vertices (-1,-1)-(1,1)
out vec2 fragCoord;

void main()
{
    fragCoord = aPos * 0.5 + 0.5; // To [0,1] range
    gl_Position = vec4(aPos, 0.0, 1.0);
}
```

---

### **Fragment Shader (`raycast.frag`)**

```glsl
#version 330 core

// Inputs
in vec2 fragCoord;

// Uniforms
uniform sampler2D uMap;    // 2D map, grayscale: 1.0=wall, 0.0=empty
uniform vec2 uMapSize;     // Size of the map in texels (e.g. 32,32)
uniform vec2 uPlayerPos;   // Player position in map coordinates (e.g. (3.5, 2.5))
uniform vec2 uPlayerDir;   // Forward direction (unit vector)
uniform vec2 uCameraPlane; // Perpendicular to uPlayerDir, controls FOV

out vec4 FragColor;

void main()
{
    // Screen x in [-1,1]
    float screenX = fragCoord.x * 2.0 - 1.0;

    // Calculate ray direction for this pixel (column)
    vec2 rayDir = uPlayerDir + uCameraPlane * screenX;

    // Map cell coordinates and initial step
    vec2 mapPos = floor(uPlayerPos);
    vec2 deltaDist = abs(vec2(1.0) / rayDir);
    vec2 sideDist;
    ivec2 step;

    // Calculate step and initial sideDist
    if(rayDir.x < 0.0) {
        step.x = -1;
        sideDist.x = (uPlayerPos.x - mapPos.x) * deltaDist.x;
    } else {
        step.x = 1;
        sideDist.x = (mapPos.x + 1.0 - uPlayerPos.x) * deltaDist.x;
    }
    if(rayDir.y < 0.0) {
        step.y = -1;
        sideDist.y = (uPlayerPos.y - mapPos.y) * deltaDist.y;
    } else {
        step.y = 1;
        sideDist.y = (mapPos.y + 1.0 - uPlayerPos.y) * deltaDist.y;
    }

    // Perform DDA
    int hit = 0;
    int side = 0; // 0: x, 1: y
    vec2 mapCheck = mapPos;
    for(int i=0; i<64; ++i) { // Max ray length
        if(sideDist.x < sideDist.y) {
            sideDist.x += deltaDist.x;
            mapCheck.x += float(step.x);
            side = 0;
        } else {
            sideDist.y += deltaDist.y;
            mapCheck.y += float(step.y);
            side = 1;
        }
        // Sample map texture (texel center)
        vec2 mapUV = (mapCheck + 0.5) / uMapSize;
        float cell = texture(uMap, mapUV).r;
        if(cell > 0.5) { // Wall found
            hit = 1;
            break;
        }
    }

    // Simple wall shading based on side
    if(hit == 1) {
        float shade = (side == 0) ? 1.0 : 0.7; // Darker for y-sides
        FragColor = vec4(vec3(shade), 1.0);
    } else {
        FragColor = vec4(0.2, 0.2, 0.25, 1.0); // Background color
    }
}
```

---

### **How to use:**

- Render a fullscreen quad using these shaders.
- Pass the following uniforms:
    - `uMap`: 2D texture representing your map (1=wall, 0=empty).
    - `uMapSize`: size of the map (vec2).
    - `uPlayerPos`: player’s position (vec2).
    - `uPlayerDir`: player’s direction (vec2, normalized).
    - `uCameraPlane`: perpendicular to direction, controls FOV (for FOV=66°, use e.g. `(uPlayerDir.y * 0.66, -uPlayerDir.x * 0.66)`).

This is a **basic raycaster**. You can extend it to render textures, sprites, etc.

