## 4. Recording and Playback (Kotlin)

**Minimal example using `AudioRecord` and `AudioTrack`:**

```kotlin
import android.media.AudioFormat
import android.media.AudioRecord
import android.media.AudioTrack
import android.media.MediaRecorder
import android.media.AudioManager
import com.example.myapp.AudioProcessor

class ReverbMic {
    private val sampleRate = 48000
    private val bufferSize = AudioRecord.getMinBufferSize(
        sampleRate,
        AudioFormat.CHANNEL_IN_MONO,
        AudioFormat.ENCODING_PCM_16BIT
    )

    private val audioRecord = AudioRecord(
        MediaRecorder.AudioSource.MIC,
        sampleRate,
        AudioFormat.CHANNEL_IN_MONO,
        AudioFormat.ENCODING_PCM_16BIT,
        bufferSize
    )

    private val audioTrack = AudioTrack(
        AudioManager.STREAM_MUSIC,
        sampleRate,
        AudioFormat.CHANNEL_OUT_MONO,
        AudioFormat.ENCODING_PCM_16BIT,
        bufferSize,
        AudioTrack.MODE_STREAM
    )

    @Volatile
    var isRunning = false

    fun start() {
        isRunning = true
        audioRecord.startRecording()
        audioTrack.play()

        Thread {
            val inputBuffer = ShortArray(bufferSize)
            val outputBuffer = ShortArray(bufferSize)

            while (isRunning) {
                val read = audioRecord.read(inputBuffer, 0, bufferSize)
                if (read > 0) {
                    AudioProcessor.processReverb(inputBuffer, outputBuffer, read)
                    audioTrack.write(outputBuffer, 0, read)
                }
            }
            audioRecord.stop()
            audioTrack.stop()
        }.start()
    }

    fun stop() {
        isRunning = false
    }
}
```

---

### **Usage Example**

```kotlin
val reverbMic = ReverbMic()
reverbMic.start()

// ... later
reverbMic.stop()
```

