## 2. **Backend (`server.js`)**

Install dependencies:  
```sh
npm init -y
npm install express pg cors
```

Create `server.js`:

```js
const express = require('express');
const cors = require('cors');
const { Pool } = require('pg');

const app = express();
const pool = new Pool({
  user: 'postgres',
  password: 'your_password',   // <-- change this
  host: 'localhost',
  port: 5432,
  database: 'your_db_name'     // <-- change this
});

app.use(cors());
app.use(express.json());

// Create a todo
app.post('/todos', async (req, res) => {
  try {
    const { description } = req.body;
    const newTodo = await pool.query(
      'INSERT INTO todos (description) VALUES ($1) RETURNING *',
      [description]
    );
    res.json(newTodo.rows[0]);
  } catch (err) {
    console.error(err.message);
  }
});

// Get all todos
app.get('/todos', async (req, res) => {
  try {
    const allTodos = await pool.query('SELECT * FROM todos');
    res.json(allTodos.rows);
  } catch (err) {
    console.error(err.message);
  }
});

// Delete a todo
app.delete('/todos/:id', async (req, res) => {
  try {
    const { id } = req.params;
    await pool.query('DELETE FROM todos WHERE todo_id = $1', [id]);
    res.json({ message: 'Todo deleted' });
  } catch (err) {
    console.error(err.message);
  }
});

const PORT = 5000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

---

## 3. **Frontend (`App.js` in React)**

Create your React app if you haven't:

```sh
npx create-react-app pern-todo-client
cd pern-todo-client
npm install axios
```

Replace the contents of `src/App.js` with:

```jsx
import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [description, setDescription] = useState('');
  const [todos, setTodos] = useState([]);

  const fetchTodos = async () => {
    const res = await axios.get('http://localhost:5000/todos');
    setTodos(res.data);
  };

  useEffect(() => {
    fetchTodos();
  }, []);

  const addTodo = async (e) => {
    e.preventDefault();
    if (!description.trim()) return;
    await axios.post('http://localhost:5000/todos', { description });
    setDescription('');
    fetchTodos();
  };

  const deleteTodo = async (id) => {
    await axios.delete(`http://localhost:5000/todos/${id}`);
    fetchTodos();
  };

  return (
    <div style={{ maxWidth: 500, margin: '2rem auto', fontFamily: 'sans-serif' }}>
      <h2>PERN Stack To-Do List</h2>
      <form onSubmit={addTodo}>
        <input
          type="text"
          value={description}
          placeholder="Add new todo"
          onChange={e => setDescription(e.target.value)}
        />
        <button type="submit">Add</button>
      </form>
      <ul>
        {todos.map(todo => (
          <li key={todo.todo_id}>
            {todo.description}
            <button onClick={() => deleteTodo(todo.todo_id)} style={{ marginLeft: 10 }}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```

