Absolutely! Below is a **simple implementation of a vanilla RNN in plain TypeScript**, with just arrays and basic math (no external libraries). This RNN will take a sequence of numbers as input and predict the next value in the sequence.

This is a *very* minimal example for learning purposes only.

---

```typescript
// Activation function and its derivative
function tanh(x: number): number {
  return Math.tanh(x);
}

function dtanh(x: number): number {
  const t = tanh(x);
  return 1 - t * t;
}

// Utility: random number between -1 and 1
function rand(): number {
  return Math.random() * 2 - 1;
}

// RNN Cell
class SimpleRNN {
  inputSize: number;
  hiddenSize: number;
  outputSize: number;

  // Weights
  Wx: number[][];
  Wh: number[][];
  Wy: number[][];

  // Biases
  bh: number[];
  by: number[];

  // Hidden state
  h: number[];

  constructor(inputSize: number, hiddenSize: number, outputSize: number) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize;

    // Initialize weights and biases
    this.Wx = Array.from({ length: hiddenSize }, () =>
      Array.from({ length: inputSize }, rand)
    );
    this.Wh = Array.from({ length: hiddenSize }, () =>
      Array.from({ length: hiddenSize }, rand)
    );
    this.Wy = Array.from({ length: outputSize }, () =>
      Array.from({ length: hiddenSize }, rand)
    );
    this.bh = Array.from({ length: hiddenSize }, rand);
    this.by = Array.from({ length: outputSize }, rand);

    // Initial hidden state
    this.h = Array(hiddenSize).fill(0);
  }

  // Single time step forward
  step(x: number[]): number[] {
    // h = tanh(Wx * x + Wh * h + bh)
    let h_new = this.bh.slice();
    for (let i = 0; i < this.hiddenSize; i++) {
      for (let j = 0; j < this.inputSize; j++) {
        h_new[i] += this.Wx[i][j] * x[j];
      }
      for (let j = 0; j < this.hiddenSize; j++) {
        h_new[i] += this.Wh[i][j] * this.h[j];
      }
      h_new[i] = tanh(h_new[i]);
    }
    this.h = h_new;

    // y = Wy * h + by
    let y = this.by.slice();
    for (let i = 0; i < this.outputSize; i++) {
      for (let j = 0; j < this.hiddenSize; j++) {
        y[i] += this.Wy[i][j] * this.h[j];
      }
    }
    return y;
  }

  // Reset hidden state
  reset() {
    this.h = Array(this.hiddenSize).fill(0);
  }
}

// Example usage:
const rnn = new SimpleRNN(1, 4, 1);

// Generate a simple sequence: [1, 2, 3, 4], want to predict next values.
const inputSeq = [[1], [2], [3], [4]];
rnn.reset();
console.log("RNN predictions:");
for (const x of inputSeq) {
  const y = rnn.step(x);
  console.log(`Input: ${x[0]}, Output: ${y[0].toFixed(3)}`);
}
```

---

**Notes:**
- This does not include backpropagation or training—just forward passes.
- To actually *train* this RNN, you'd need to implement backpropagation-through-time and gradient descent.
- This is a pedagogical example; real RNNs for production should use libraries like TensorFlow.js or similar.

