## `sprite-editor.js`

```javascript
// Sprite Editor Logic
const canvas = document.getElementById('spriteCanvas');
const ctx = canvas.getContext('2d');
const colorPicker = document.getElementById('colorPicker');
const clearBtn = document.getElementById('clearBtn');
const gridSizeSelect = document.getElementById('gridSize');
const downloadBtn = document.getElementById('downloadBtn');

let gridSize = parseInt(gridSizeSelect.value);
let pixelSize = canvas.width / gridSize;
let drawing = false;

// 2D Array for sprite pixels (default 16x16, initialized to transparent)
let sprite = Array.from({ length: gridSize }, () => Array.from({ length: gridSize }, () => null));

function drawGrid() {
  // Draw pixels
  for (let y = 0; y < gridSize; y++) {
    for (let x = 0; x < gridSize; x++) {
      if (sprite[y][x]) {
        ctx.fillStyle = sprite[y][x];
        ctx.fillRect(x * pixelSize, y * pixelSize, pixelSize, pixelSize);
      } else {
        ctx.clearRect(x * pixelSize, y * pixelSize, pixelSize, pixelSize);
      }
    }
  }
  // Draw grid lines
  ctx.strokeStyle = "#444";
  for (let i = 0; i <= gridSize; i++) {
    // Vertical
    ctx.beginPath();
    ctx.moveTo(i * pixelSize, 0);
    ctx.lineTo(i * pixelSize, canvas.height);
    ctx.stroke();
    // Horizontal
    ctx.beginPath();
    ctx.moveTo(0, i * pixelSize);
    ctx.lineTo(canvas.width, i * pixelSize);
    ctx.stroke();
  }
}

function setPixel(e) {
  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;
  const x = Math.floor(mx / pixelSize);
  const y = Math.floor(my / pixelSize);
  if (x >= 0 && x < gridSize && y >= 0 && y < gridSize) {
    sprite[y][x] = colorPicker.value;
    drawGrid();
  }
}

function erasePixel(e) {
  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;
  const x = Math.floor(mx / pixelSize);
  const y = Math.floor(my / pixelSize);
  if (x >= 0 && x < gridSize && y >= 0 && y < gridSize) {
    sprite[y][x] = null;
    drawGrid();
  }
}

canvas.addEventListener('mousedown', (e) => {
  drawing = true;
  if (e.button === 0) setPixel(e);       // Left-click: Draw
  else if (e.button === 2) erasePixel(e); // Right-click: Erase
});
canvas.addEventListener('mousemove', (e) => {
  if (drawing) {
    if (e.buttons === 1) setPixel(e);
    else if (e.buttons === 2) erasePixel(e);
  }
});
canvas.addEventListener('mouseup', () => drawing = false);
canvas.addEventListener('mouseleave', () => drawing = false);
canvas.addEventListener('contextmenu', (e) => e.preventDefault()); // Disable right-click menu

clearBtn.addEventListener('click', () => {
  sprite = Array.from({ length: gridSize }, () => Array.from({ length: gridSize }, () => null));
  drawGrid();
});

gridSizeSelect.addEventListener('change', () => {
  gridSize = parseInt(gridSizeSelect.value);
  pixelSize = canvas.width / gridSize;
  sprite = Array.from({ length: gridSize }, () => Array.from({ length: gridSize }, () => null));
  drawGrid();
});

