- The Bash `source "$DIR/../video.sh"` is replaced by a call to the shell to get the filename, but you may want to port `get-filename` logic directly if possible.
- `exa` and `video-compare` are called as in Bash.
- Perl's `system` is used for external commands.
- The Perl script is written for Unix-like systems.
- Make the script executable and run as `perl script.pl ...args...`

---

```perl
#!/usr/bin/env perl
use strict;
use warnings;
use File::Basename;
use Cwd 'abs_path';
use Getopt::Long;

# Get script directory
my $DIR = dirname(abs_path($0));

# Source video.sh to get get-filename (simulate)
sub get_filename {
    my $path = shift;
    my ($name) = $path =~ m{([^/]+)$};
    $name =~ s/\.[^\.]+$//; # remove extension
    return $name;
}

# Argument variables
my ($quality, $preset, $resize, $noise, $input_file);

# Parse arguments (mimic Bash)
GetOptions(
    "q|quality=s" => \$quality,
    "p|preset=s"  => \$preset,
    "r|resize=s"  => \$resize,
    "n|noise=s"   => \$noise,
);

# Remaining argument is input_file
$input_file = shift @ARGV if @ARGV;

# Check input file existence
if (!defined $input_file or !-f $input_file) {
    print STDERR "FILE NOT FOUND: " . ($input_file // "") . "\n";
}

# Check for required args
if (!defined $quality || !defined $preset || !defined $input_file) {
    print STDERR "Usage: $0 -q|--quality <quality> -p|--preset <preset> [-n|--noise <noise_level>] [-r|--resize <size>] <input_file>\n";
    exit 1;
}

my $file_path = abs_path($input_file);
my $file_name = get_filename($file_path);

my $chunk_method = "ffms2";

my $output_name = "${file_name}.reencode.av1an.aom.rf${quality}.p${preset}";
my $metadata_comment = "reencoded with av1an(aom), 10-bit, cpu-used=${preset}, cq=${quality}, chunk-method=$chunk_method";

if (defined $noise && $noise ne "") {
    $output_name .= ".noise$noise";
} else {
    $noise = 10;
}

if (defined $resize && $resize ne "") {
    $output_name .= ".${resize}p";
}

# Set ulimit (not portable, but we can call sh)
system("ulimit -n 2048") == 0 or warn "Could not set ulimit";

my $threads = 2;

# Compose ffmpeg filter string
my $ffmpeg_vf = "";
if (defined $resize && $resize ne "") {
    $ffmpeg_vf = " -vf 'scale=-1:${resize}'";
}

my $av1an_cmd = join(" ",
    "av1an --verbose",
    "-i \"$file_path\"",
    "--encoder aom",
    "--workers 4",
    "--resume",
    "--extra-split 300",
    "--ignore-frame-mismatch",
    "--audio-params \" -an \"",
    "--ffmpeg \" -an$ffmpeg_vf\"",
    "--split-method av-scenechange --chunk-method $chunk_method --concat mkvmerge",
    "--set-thread-affinity=\"$threads\"",
    "--photon-noise=\"$noise\"",
    "--video-params \"",
    "--bit-depth=10",
    "--threads=$threads",
    "--end-usage=q --cq-level=$quality --cpu-used=$preset",
    "--tile-columns=0 --tile-rows=0",
    "--tune-content=psy --tune=ssim",
    "--lag-in-frames=64",
    "--enable-keyframe-filtering=1 --disable-kf --kf-max-dist=9999",
    "--enable-qm=1 --deltaq-mode=0 --aq-mode=0 --quant-b-adapt=1",
    "--enable-fwd-kf=0 --arnr-strength=4 --sb-size=dynamic --enable-dnl-denoising=0",
    "\"",
    "-o \"${output_name}.audioless.mkv\""
);

system($av1an_cmd) == 0 or die "av1an command failed";

# Put the audio back and convert to mp4
my $ffmpeg_cmd = join(" ",
    "ffmpeg -loglevel warning -hide_banner",
    "-i \"${output_name}.audioless.mkv\" -i \"$file_path\"",
    "-c copy -map 0:v -map 1:a",
    "-metadata comment=\"$metadata_comment\"",
    "\"${output_name}.mp4\""
);

system($ffmpeg_cmd) == 0 or die "ffmpeg command failed";

# Remove intermediate mkv
system("rm -rf \"${output_name}.audioless.mkv\"") == 0 or warn "Could not remove temp mkv";

print "\n\n";
system("exa -al --color=always --no-permissions --no-user --time-style=long-iso \"$input_file\" \"${output_name}.mp4\"");

print "\n";
print "video-compare \"$input_file\" \"${output_name}.mp4\"\n";

print "\n✅ FINISHED\n";
```

