Certainly! Here is a simple **Connect-4** game implemented in Python, playable in the console by two human players.

---

```python
ROWS = 6
COLS = 7

def create_board():
    return [[' ' for _ in range(COLS)] for _ in range(ROWS)]

def print_board(board):
    print(' 1 2 3 4 5 6 7')
    for row in board:
        print('|' + '|'.join(row) + '|')
    print('-' * (COLS * 2 + 1))

def is_valid_location(board, col):
    return board[0][col] == ' '

def get_next_open_row(board, col):
    for r in range(ROWS-1, -1, -1):
        if board[r][col] == ' ':
            return r
    return None

def drop_piece(board, row, col, piece):
    board[row][col] = piece

def winning_move(board, piece):
    # Check horizontal
    for r in range(ROWS):
        for c in range(COLS-3):
            if all(board[r][c+i] == piece for i in range(4)):
                return True
    # Check vertical
    for c in range(COLS):
        for r in range(ROWS-3):
            if all(board[r+i][c] == piece for i in range(4)):
                return True
    # Check positively sloped diagonals
    for r in range(ROWS-3):
        for c in range(COLS-3):
            if all(board[r+i][c+i] == piece for i in range(4)):
                return True
    # Check negatively sloped diagonals
    for r in range(3, ROWS):
        for c in range(COLS-3):
            if all(board[r-i][c+i] == piece for i in range(4)):
                return True
    return False

def is_board_full(board):
    return all(board[0][c] != ' ' for c in range(COLS))

def main():
    board = create_board()
    game_over = False
    turn = 0
    print_board(board)
    while not game_over:
        piece = 'X' if turn % 2 == 0 else 'O'
        try:
            col = int(input(f"Player {piece}, select column (1-{COLS}): ")) - 1
        except ValueError:
            print("Invalid input. Try again.")
            continue
        if 0 <= col < COLS:
            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, piece)
                print_board(board)
                if winning_move(board, piece):
                    print(f"Player {piece} wins!")
                    game_over = True
                elif is_board_full(board):
                    print("It's a draw!")
                    game_over = True
                else:
                    turn += 1
            else:
                print("Column is full. Try another one.")
        else:
            print("Column out of range. Try again.")

if __name__ == "__main__":
    main()
```

---

**How to play:**
- Run the script in a Python environment.
- Players alternate entering column numbers (1-7) to drop their pieces.
- First to connect four horizontally, vertically, or diagonally wins.

