To **extract hashtags from a string in C#**, you can use **regular expressions**. Here’s a simple code example:

```csharp
using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

class Program
{
    static void Main()
    {
        string text = "Here are some #hashtags in a #CSharp string! #100DaysOfCode #csharp_dev";
        List<string> hashtags = ExtractHashtags(text);

        foreach (var tag in hashtags)
        {
            Console.WriteLine(tag);
        }
    }

    static List<string> ExtractHashtags(string input)
    {
        var matches = Regex.Matches(input, @"#\w+");
        var hashtags = new List<string>();
        foreach (Match match in matches)
        {
